# Attaches a VHDX with the virtual disk API and mounts its volume at an empty folder, without
# diskpart, the Virtual Disk Service or the storage cmdlets, which take seconds to start on a new
# runner. Prints the time of each step. The APIs are in NmbVhd.cs, which the scripts job compiles
# to NmbVhd.dll: compiling it here takes over 10 seconds on a new runner.
#
#   vhd.ps1 -Path C:\a\_temp\workspace.vhdx -MountFolder C:\a\vscode [-CachedIo] [-Trust]
#   vhd.ps1 -Path C:\a\_temp\image.vhdx -Create [-MaximumSizeGB 200] [-BlockSizeMB 1]
#   vhd.ps1 -CloneList C:\a\_temp\clones.txt
#
# -CachedIo opens the VHDX through the file system cache of drive C, so that a VHDX that was just
# restored is read from memory instead of from the disk. It tries the versions of the open
# parameters and the flags that may allow it, and falls back to uncached I/O. -Trust trusts the
# Dev Drive of the VHDX on this machine, like a Dev Drive that it formats.
# -Create creates an empty dynamic VHDX instead. diskpart always uses blocks of 32 MB, which the
# VHDX file allocates in full as soon as the file system writes to them.
# -CloneList clones the copies of "original TAB copy" lines from their originals on ReFS.
param(
	[string] $Path,
	[string] $MountFolder,
	[switch] $CachedIo,
	[switch] $Trust,
	[switch] $Create,
	[int] $MaximumSizeGB = 200,
	[int] $BlockSizeMB = 1,
	[string] $CloneList
)

$ErrorActionPreference = 'Stop'
$watch = [Diagnostics.Stopwatch]::StartNew()
function Step([string] $name) {
	Write-Output ("{0,8:N3}s  {1}" -f $watch.Elapsed.TotalSeconds, $name)
}

$dll = Join-Path $PSScriptRoot 'NmbVhd.dll'
if (Test-Path $dll) {
	Add-Type -Path $dll
	Step 'loaded NmbVhd.dll'
} else {
	Add-Type -Path (Join-Path $PSScriptRoot 'NmbVhd.cs')
	Step 'compiled NmbVhd.cs'
}

if ($CloneList) {
	$summary = [NmbVhd]::CloneFiles($CloneList, 16)
	Step "cloned: $summary"
	return
}
if (-not $Path) { throw 'Missing -Path' }
if ($Create) {
	[NmbVhd]::Create($Path, [uint64]$MaximumSizeGB * 1GB, [uint32]$BlockSizeMB * 1MB)
	Step "created $Path, $MaximumSizeGB GB in blocks of $BlockSizeMB MB"
	return
}
if (-not $MountFolder) { throw 'Missing -MountFolder' }

# Versions of OPEN_VIRTUAL_DISK_PARAMETERS and open flags: OPEN_VIRTUAL_DISK_FLAG_CACHED_IO (0x8),
# with OPEN_VIRTUAL_DISK_FLAG_NO_WRITE_HARDENING (0x100), then without either
$attempts = @()
if ($CachedIo) {
	$attempts += @(@(1, 0x8), @(2, 0x8), @(3, 0x8), @(2, 0x108), @(3, 0x108))
}
$attempts += , @(1, 0x0)
$disk = -1
foreach ($attempt in $attempts) {
	$result = [NmbVhd]::TryAttach($Path, [uint32]$attempt[0], [uint32]$attempt[1], [ref]$disk)
	Step ("open parameters version {0}, open flags 0x{1:x}: {2}" -f $attempt[0], $attempt[1], $(if ($result -eq 0) { "attached as disk $disk" } else { "error $result" }))
	if ($result -eq 0) { break }
}
if ($disk -lt 0) { throw 'The VHDX did not attach' }
$volume = [NmbVhd]::WaitForVolume($disk, 60000)
Step "found volume $volume"
[NmbVhd]::Mount("$($MountFolder.TrimEnd('\'))\", $volume)
Step "mounted at $MountFolder"
if ($env:GITHUB_ENV) {
	# For the steps that write through the volume path, which bypasses the mount point
	Add-Content -Path $env:GITHUB_ENV -Value "NMB_VOLUME=$volume"
}
Get-ChildItem -Force $MountFolder | Out-Null
Step 'listed the root folder'
if ($Trust) {
	fsutil devdrv trust $MountFolder | Out-Host
	Step 'trusted the Dev Drive'
	fsutil devdrv query $MountFolder | Out-Host
}
